protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex removed: Cosmos DB indexing is managed via the container's
    // indexing policy (Azure Portal / Bicep / Terraform), not EF Core.
    // In EF Core 9 calling HasIndex on a Cosmos entity throws at startup.

    modelBuilder.Entity<Product>(b =>
    {
        b.ToContainer("Products");

        // Preserve EF Core 8 discriminator property name ("Discriminator")
        // so existing documents and direct SQL queries that reference
        // c.Discriminator continue to work.  EF Core 9 defaults to "$type".
        b.HasDiscriminator<string>("Discriminator");

        // Preserve EF Core 8 compound id format ("Product|123") so that
        // existing 500K documents remain readable via FindAsync / point-reads.
        // EF Core 9 defaults to key-only ids (e.g. "123").
        b.HasRootDiscriminatorInJsonId(true);
    });
}

